draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // character
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 - 30 + 20*Math.sin(t), H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 + 30 + 20*Math.sin(t), H/2 + 40);
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20 + 10*Math.sin(2*t), H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20 + 10*Math.sin(2*t), H/2 + 70);
  ctx.stroke();

  // caffeine energy
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 20, 10 + 10*Math.sin(t), 0, 2*Math.PI);
  ctx.stroke();

  // crash
  if (t > Math.PI) {
    ctx.beginPath();
    ctx.moveTo(W/2, H/2 + 50);
    ctx.lineTo(W/2, H/2 + 70 + 20*Math.sin(t - Math.PI));
    ctx.stroke();
  }

  ctx.restore();
}
